// Table measured on Java (JDK 21.0.2) by the probe `ProbeExchange.java`
// (maintainer-only probe): `ExchangeEngine.parse`,
// `parseLine`, `sentDefaults`, `activeReceivedFields` and `QsoContextFactory` scenarios.
// Rows are not edited by hand — they are regenerated by the script `gen_swift.py`. The result is the probe
// text (`ExchangeMeasuredTests.value`/`map`/`exception` compose it the same way); YAML `@file`
// comes from fixtures.

@testable import MCLCore

enum ExchangeMeasured {
    enum Outcome: Sendable, Equatable {
        case text(String)
        /// Java fails with a NullPointerException; Swift is lenient (a deliberate divergence from Java v1.1.1).
        case npe
    }

    /// `parse(field, raw)`; the field is the single element of `exchange.received` from `{exchange: {received: [field]}}`.
    struct ParseRow: Sendable, CustomStringConvertible {
        let label: String
        let field: String
        let raw: String?
        let java: Outcome
        init(_ label: String, _ field: String, _ raw: String?, _ java: Outcome) {
            self.label = label; self.field = field; self.raw = raw; self.java = java
        }
        var description: String { label }
    }

    /// `parseLine(exchange.received, line)`.
    struct LineRow: Sendable, CustomStringConvertible {
        let label: String
        let yaml: String
        let line: String?
        let java: Outcome
        init(_ label: String, _ yaml: String, _ line: String?, _ java: Outcome) {
            self.label = label; self.yaml = yaml; self.line = line; self.java = java
        }
        var description: String { label }
    }

    enum Rover: Sendable {
        /// Java constructor without `roverQth` (→ `""`).
        case defaultRover
        case rover(String?)
    }

    /// `sentDefaults(definition, ExchangeContext(mode, serial, station, rover))`; `station == nil`
    /// is Java `null`, `[]` is `Map.of()`, otherwise `HashMap`.
    struct SentRow: Sendable, CustomStringConvertible {
        let label: String
        let yaml: String
        let mode: Mode?
        let serial: Int32
        let station: [(String?, String?)]?
        let rover: Rover
        let java: Outcome
        init(_ label: String, _ yaml: String, _ mode: Mode?, _ serial: Int32,
             _ station: [(String?, String?)]?, _ rover: Rover, _ java: Outcome) {
            self.label = label; self.yaml = yaml; self.mode = mode; self.serial = serial
            self.station = station; self.rover = rover; self.java = java
        }
        var description: String { label }
    }

    /// `activeReceivedFields(definition, workedClass)` → ids separated by `;`.
    struct ActiveRow: Sendable, CustomStringConvertible {
        let label: String
        let yaml: String
        let workedClass: String?
        let java: Outcome
        init(_ label: String, _ yaml: String, _ workedClass: String?, _ java: Outcome) {
            self.label = label; self.yaml = yaml; self.workedClass = workedClass; self.java = java
        }
        var description: String { label }
    }

